WITH daily_agg AS ( SELECT cr.cr_returned_date_sk AS return_date, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_return_quantity) AS total_return_qty, cp.cp_department, r.r_reason_desc, SUM(CASE WHEN cd.cd_gender = 'F' THEN 1 ELSE 0 END) AS female_cnt, COUNT(*) AS total_cnt FROM catalog_returns cr JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk JOIN customer_demographics cd ON cr.cr_returning_cdemo_sk = cd.cd_demo_sk WHERE cr.cr_returned_date_sk >= 20230101 GROUP BY cr.cr_returned_date_sk, cp.cp_department, r.r_reason_desc ) SELECT return_date, total_return_amount, total_return_qty, cp_department, r_reason_desc, CAST(female_cnt AS double) / total_cnt AS female_ratio, MAX(total_return_amount) OVER (PARTITION BY cp_department) AS max_dept_amount, MIN(total_return_amount) OVER (PARTITION BY cp_department) AS min_dept_amount, SUM(total_return_amount) OVER (ORDER BY return_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount FROM daily_agg ORDER BY return_date
